const input=$json.body??$json;
const offer=input.revised_offer??{};
const delivery=String(input.delivery_status||input.receipt_status||"").toLowerCase();
const sellerResponse=String(input.seller_response||input.message||input.inbound_message||"").trim();
const dispatchId=String(input.dispatch_id||offer.dispatch_id||"").trim();
const channel=String(offer.channel||input.channel||"").toLowerCase();
const recipient=String(offer.recipient||input.recipient||"").trim();
const dnc=Boolean(input.dnc||input.do_not_contact);
const blockers=Array.isArray(input.blockers)?input.blockers:[];
let state="awaiting_delivery",status="dispatch_pending",nextWorkflow="WF-295",human=false,reason="revised offer dispatch is awaiting provider delivery receipt";
if(dnc){state="blocked";status="blocked_dnc";nextWorkflow="WF-126";human=true;reason="seller is marked do-not-contact";}
else if(blockers.length){state="blocked";status="blocked";nextWorkflow="WF-126";human=true;reason="active blockers present";}
else if(!dispatchId||!recipient||!["sms","email"].includes(channel)){state="invalid_dispatch";status="dispatch_identity_invalid";nextWorkflow="WF-126";human=true;reason="dispatch identity, recipient, and channel are required";}
else if(sellerResponse){state="seller_response_received";status="response_received";nextWorkflow="WF-296";reason="seller response received for revised offer";}
else if(["delivered","delivery_confirmed","sent"].includes(delivery)){state="delivered";status="delivered_awaiting_response";nextWorkflow="WF-296";reason="revised offer delivered; awaiting seller response";}
else if(["failed","undelivered","bounced","rejected"].includes(delivery)){state="delivery_failed";status="delivery_failed";nextWorkflow="WF-298";human=true;reason="revised offer delivery failed; regenerate or select another channel";}
else if(["timeout","expired"].includes(delivery)){state="response_timeout";status="response_timeout";nextWorkflow="WF-290";reason="seller response window expired";}
const idempotencyKey=input.idempotency_key||`wf-299:${dispatchId||input.deal_id||"unknown"}:${input.provider_event_id||input.version||1}`;
return [{json:{...input,workflow:"WF-299",workflow_name:"Revised Offer Dispatch → Delivery Receipt → Seller Response Loop Controller",status,response_loop:{state,dispatch_id:dispatchId,channel,recipient,delivery_status:delivery||null,seller_response_present:Boolean(sellerResponse),reason},next_workflow:nextWorkflow,human_review_required:human,audit:{event_type:"revised_offer_delivery_response_loop",idempotency_key:idempotencyKey}}}];
